"""FREQTBL / FREQTBH images for bare-``.swm`` playback, per (version, driver).

A bare ``.swm`` carries no player image, so the player's lookups past the 96-note
``FREQTBL`` would otherwise read a constant fallback. Each release+driver build sits
different bytes over that region, and the pre-1.8 first-frame quirk is per release.
This ships the exact 256-byte spans and the first-frame flag for each pair, taken
from that release's own ``.sid`` exports (its player at ``PLAYERADDR``) and asserted
byte-identical across every tune of a release+driver.

Regenerate with ``python scripts/gen_player_images.py``; only this module is committed.
"""

from __future__ import annotations

# Releases with a shipped player image.
PLAYER_VERSIONS = ("1.7", "1.97")

# Latest release; the default for player_version.
LATEST_PLAYER_VERSION = "1.97"

# (version, driver_type) -> (freq_lo_image, freq_hi_image, first_frame_freq_by_track);
# the 256-byte FREQTBL / FREQTBH spans as the 6502 pitch table for that build.
_PLAYER_IMAGES = {
    ("1.7", 0): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        True,
    ),
    ("1.7", 2): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        False,
    ),
    ("1.97", 0): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        False,
    ),
    ("1.97", 2): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        False,
    ),
    ("1.97", 3): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        False,
    ),
    ("1.97", 4): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        False,
    ),
    ("1.97", 5): (
        bytes.fromhex(
            ""
        ),
        bytes.fromhex(
            ""
        ),
        False,
    ),
}


def image_for(version: str, driver_type: int) -> tuple[bytes, bytes, bool] | None:
    """The image for ``(version, driver_type)`` or None if that pair is not shipped."""
    return _PLAYER_IMAGES.get((version, driver_type))
